```pascal
program BinarySubstringQueries;

uses
  SysUtils;

type
  TSubstringValue = record
    Value: Integer;
    Start, EndIndex: Integer;
  end;

procedure PrecomputeSubstrings(s: string; var values: array of TSubstringValue);
var
  i, j, len: Integer;
  value: Integer;
  sb: array of String;
  sbValue: array of TSubstringValue;
begin
  len := Length(s);
  SetLength(values, len);
  for i := 0 to len - 1 do
  begin
    value := 0;
    for j := i to len - 1 do
    begin
      value := value shl 1 + (Ord(s[j]) - Ord('0'));
      SetLength(sb, Length(sb) + 1);
      sb[High(sb)] := Copy(s, i, j - i + 1);
      SetLength(sbValue, Length(sbValue) + 1);
      sbValue[High(sbValue)].Value := value;
      sbValue[High(sbValue)].Start := i;
      sbValue[High(sbValue)].EndIndex := j;
    end;
  end;
end;

function FindQueryResult(values: array of TSubstringValue; first, second: Integer): TSubstringValue;
var
  i, j: Integer;
