  begin
    j := values[i].Value;
    if (j ^ first = second) and (j < resultValue.Value) then
    begin
      resultValue.Value := j;
      resultValue.Start := values[i].Start;
      resultValue.EndIndex := values[i].EndIndex;
    end;
  end;

  if resultValue.Value = -1 then
    Exit(resultValue);

  for i := 0 to High(values) do
  begin
    j := values[i].Value;
    if (j ^ first = second) and (j = resultValue.Value) then
    begin
      if values[i].Start < resultValue.Start then
      begin
        resultValue.Start := values[i].Start;
        resultValue.EndIndex := values[i].EndIndex;
      end;
    end;
  end;

  Exit(resultValue);
end;

function Solve(s: string; queries: array of array of Integer): array of array of Integer;
var
  values: array of TSubstringValue;
  i, j: Integer;
  resultArray: array of array of Integer;
