     */
    $is_prime = function($n) {
        // Numbers less than 2 are not prime
        if ($n < 2) {
            return false;
        }

        // Check for divisors from 2 to sqrt(n)
        // Only need to check up to sqrt(n) because if n has a divisor greater than sqrt(n),
        // it must also have one less than sqrt(n)
        $sqrt_n = (int)sqrt($n);
        for ($i = 2; $i <= $sqrt_n; $i++) {
            if ($n % $i == 0) {
                return false; // Found a divisor, not prime
            }
        }

        return true; // No divisors found, it's prime
    };

    // Step 1: Extract unique values from the array (using array_unique)
    // Then filter only those whose absolute value is prime
    $unique_values = array_unique($arr);
    $primes = [];

    foreach ($unique_values as $val) {
        // We check the absolute value because primes are defined as positive integers > 1
        // But the array can contain negative numbers (e.g., -5, which has abs 5 -> prime)
        if ($is_prime(abs($val))) {
            $primes[] = $val; // Store the original value (with sign) for later use
