    public Student() {
        this.name = "未知学生";
        this.age = 0;
        this.email = "unknown@example.com";
        this.gpa = 0.0;
        System.out.println("使用无参构造函数创建了一个学生对象。");
    }

    // 2. 带参数的构造函数
    public Student(String name, int age) {
        this.name = name;
        this.age = age;
        this.email = "unknown@example.com"; // 默认邮箱
        this.gpa = 0.0;
        System.out.println("使用双参数构造函数创建学生：" + name);
    }

    // 3. 完整参数构造函数
    public Student(String name, int age, String email, double gpa) {
        this.name = name;
        this.age = age;
        this.email = email;
        this.gpa = gpa;
        System.out.println("使用完整参数构造函数创建学生：" + name);
    }

    // Getter 方法
    public String getName() {
        return name;
    }

    public int getAge() {
        return age;
    }

    public String getEmail() {
