    if ($n < 2) {
        return false; // Numbers less than 2 are not prime
    }
    for ($i = 2; $i <= sqrt($n); $i++) {
        if ($n % $i == 0) {
            return false; // If n is divisible by any number in the range, it's not prime
        }
    }
    return true; // If no divisors found, n is prime
}

// Function to compute the product of signs of prime numbers in the array
function prod_signs($arr) {
    // Get unique elements in the array
    $unique_arr = array_unique($arr);

    // Filter out non-prime numbers
    $primes = array_filter($unique_arr, 'is_prime');

    // If there are no prime numbers, return null
    if (empty($primes)) {
        return null;
    }

    // Calculate the product of signs of the prime numbers
    $result = array_reduce($primes, function($carry, $item) {
        // If the count of the prime number in the original array is even, keep the sign
        // If the count is odd, change the sign
        if (count(array_keys($arr, $item)) % 2 == 0) {
            return $carry * $item;
        } else {
            return $carry * (-$item);
        }
    }, 1); // Start with 1 as the initial carry value

    return $result;
}

// Example usage:
$example_arr = [2, -3, 2, 3, -2];
$result = prod_signs($example_arr);
echo $result; // Output will be -6
?>
```

