```php
<?php
function prodSigns($arr) {
    // Define a helper function to check if a number is prime
    function isPrime($n) {
        // Prime numbers must be greater than 1
        if ($n < 2) {
            return false;
        }
        // Check divisibility from 2 to the square root of n
        for ($i = 2; $i <= sqrt($n); $i++) {
            if ($n % $i == 0) {
                return false;
            }
        }
        return true;
    }

    // Remove duplicates and filter out prime numbers
    $primes = array_filter(array_unique($arr), 'isPrime');

    // If no prime numbers are found, return null
    if (empty($primes)) {
        return null;
    }

    // Calculate the sum of elements where their count in the original array is even
    $result = 0;
    foreach ($primes as $prime) {
        if (count(array_keys($arr, $prime)) % 2 == 0) {
            $result += $prime;
        } else {
            $result -= $prime;
        }
    }

    return $result;
}

// Example usage:
$exampleArray = [2, 3, -2, -3, 4, 5];
echo prodSigns($exampleArray); // Output will be calculated based on the logic
?>
```

