program ShortestSubstringsFinder;

{$APPTYPE CONSOLE}

uses
  SysUtils;

function ToDecimal(const BinStr: string): Integer;
var
  I: Integer;
begin
  Result := 0;
  for I := 1 to Length(BinStr) do
    if BinStr[I] = '1' then
      Inc(Result, Power(2, Length(BinStr) - I));
end;

function ToBinary(D: Integer; Len: Integer): string;
var
  I: Integer;
  BinStr: string;
begin
  BinStr := '';
  for I := 1 to Len do
    if D and 1 = 1 then
      BinStr := '1' + BinStr
    else
      BinStr := '0' + BinStr;
    D := D shr 1;
  Result := BinStr;
end;

function FindShortestSubstring(const S: string; Q: array of array of Integer): array of array of Integer;
var
  I, J, Len, Start, EndPos: Integer;
  Map: array of array of Integer;
  Query, First, Second, XORVal, DecVal: Integer;
  BinStr, Key: string;
begin
  SetLength(Map, Length(S));
  for I := 0 to High(S) do
    if S[I + 1] = '1' then
    begin
      Start := I;
      Len := 1;
      while I + Len < Length(S) do
      begin
        Inc(Len);
        DecVal := ToDecimal(Copy(S, I + 1, Len));
        Key := IntToHex(DecVal, Len);
        if not Assigned(Map[DecVal]) then
          Map[DecVal] := [];
        Map[DecVal].Add([Start, I]);
      end;
    end;

  SetLength(Result, Length(Q));
  for I := 0 to High(Q) do
  begin
    Query := Q[I][0];
    Second := Q[I][1];
    XORVal := Query xor Second;
    if Assigned(Map[XORVal]) then
    begin
      for Start in Map[XORVal] do
      begin
        EndPos := Start[1];
        DecVal := ToDecimal(Copy(S, Start[0] + 1, (EndPos - Start[0])));
        if (DecVal = XORVal) and (Start[0] < Result[I][0] or (Start[0] = Result[I][0] and Start[1] < Result[I][1])) then
          Result[I] := [Start[0], EndPos];
      end;
    end;
    if Result[I][0] = -1 then
      Result[I] := [-1, -1];
  end;
end;

var
  S: string;
  Q: array of array of Integer;
  ResultArray: array of array of Integer;
begin
  try
    S := '101101';
    Q := [[0, 5], [1, 2]];
    ResultArray := FindShortestSubstring(S, Q);
    for I := Low(ResultArray) to High(ResultArray) do
    begin
      WriteLn('[' + IntToStr(ResultArray[I][0]) + ', ' + IntToStr(ResultArray[I][1]) + ']');
    end;
  except
    on E: Exception do
      Writeln(E.ClassName, ': ', E.Message);
  end;
  ReadLn;
end.
