import Foundation

// Function to generate all substrings of a given string
func allSubstrings(_ inputString: String) -> [String] {
    let length = inputString.count
    var substrings: [String] = []
    for i in 0..<length {
        for j in i+1...length {
            let substring = String(inputString[stride(from: i, through: j-1, by: 1)])
            substrings.append(substring)
        }
    }
    return substrings
}

// Function to find the longest common substring that appears at least 'k' times across all input strings
func longestCommonSubstring(strings: [String], k: Int) -> String? {
    guard !strings.isEmpty else {
        return nil
    }

    var longestSubstring: String = ""
    for s in strings {
        for substring in allSubstrings(s) {
            let count = strings.reduce(0) { acc, str in
                acc + (str.contains(substring) ? 1 : 0)
            }
            if count >= k && substring.count > longestSubstring.count {
                longestSubstring = substring
            }
        }
    }
    return longestSubstring.isEmpty ? nil : longestSubstring
}

// Example usage
