```javascript
function sortBooksAlphabetically(books) {
    // First, we need a helper function to get the sorting key for each book.
    function getSortingKey(book) {
        // Extract the first character and determine if it's a number.
        const firstChar = book.charAt(0);
        const isNumber = /^\d/.test(firstChar);

        // If it's a number, sort it before letters.
        if (isNumber) {
            return [true, firstChar, -book.length, -book.charCodeAt(0)];
        } else {
            // For letters, use case sensitivity and descending order.
            return [false, firstChar, book.length, -book.charCodeAt(0)];
        }
    }

    // Now, we can use the Array.prototype.sort method with our custom sorting key.
    return books.sort((a, b) => {
        const keyA = getSortingKey(a);
        const keyB = getSortingKey(b);

        // Compare each part of the key.
        for (let i = 0; i < keyA.length; i++) {
            if (keyA[i] !== keyB[i]) {
                return keyA[i] - keyB[i];
            }
        }

        // If all parts are the same, keep the original order.
        return 0;
    });
}

// Example usage:
const Books = ["3 Little Pigs", "Alice in Wonderland", "1 Fish 2 Fish Red Fish Blue Fish", "1984", "Harry Potter and the Chamber of Secrets"];
const sortedBooks = sortBooksAlphabetically(Books);
console.log(sortedBooks);
```

