<?php
function prod_signs($arr) {
    // Define a helper function to check if a number is prime
    function is_prime($n) {
        if ($n < 2) {
            return false; // Numbers less than 2 are not prime
        }
        for ($i = 2; $i <= sqrt($n); $i++) {
            if ($n % $i == 0) {
                return false; // If n is divisible by any number other than 1 and itself, it's not prime
            }
        }
        return true; // If no divisors were found, n is prime
    }

    // Create an array of unique prime numbers from the input array
    $primes = [];
    foreach ($arr as $value) {
        if (is_prime(abs($value))) { // Check if the absolute value of the number is prime
            if (!in_array($value, $primes)) { // Ensure the prime number is unique
                $primes[] = $value;
            }
        }
    }

    // If no prime numbers are found, return null
    if (empty($primes)) {
        return null;
    }

    // Calculate the sum of the primes with even counts, and the negative of primes with odd counts
    $result = 0;
    foreach ($primes as $prime) {
        if (count(array_keys($arr, $prime)) % 2 == 0) { // Check if the count of the prime in the original array is even
            $result += $prime; // Add the prime to the result
        } else {
            $result -= $prime; // Subtract the prime from the result
        }
    }

    return $result; // Return the final result
}

